/**
 * Синтетические многолистовые прайсы для тестов KB-PRICE-SHEETS: по структуре задания (11 и 10 вкладок), счётчики — как в
 * таблице приёмки (межкомнатные: 30 ID, INT-008 — сметная, 150 размеров, 31 тариф фурнитуры, из них 22 с ценой;
 * металл: 20 ID, № 9 = MET-012, ALU-003/004 неактивны, ALU-007 только смета). Настоящие файлы заказчика в сессию не
 * попадали — колонки названы по тексту задания.
 */
import ExcelJS from 'exceljs';

export type Sheets = Record<string, unknown[][]>;

export async function bookXlsx(sheets: Sheets): Promise<Buffer> {
  const wb = new ExcelJS.Workbook();
  for (const [name, rows] of Object.entries(sheets)) {
    const ws = wb.addWorksheet(name);
    for (const r of rows) ws.addRow(r);
  }
  return Buffer.from(await wb.xlsx.writeBuffer());
}

