  ГОСТы: [['ГОСТ', 'Описание'], ['ГОСТ 475-2016', 'Блоки дверные деревянные и комбинированные'], ['ГОСТ 31173-2016', 'Блоки дверные стальные'], ['ГОСТ 23747-2015', 'Блоки дверные из алюминиевых сплавов']],
  Типоразмеры: [['Типоразмер', 'Значение', 'Правило для агента'], ['21-9', '900×2100 по проёму', 'размер проёма, не полотна'], ['21-10', '1000×2100 по проёму', 'размер проёма, не полотна']],
  Словарь: [['Слово', 'Значение', 'Контекст', 'Правило для агента'], ['добор', 'доборная планка', 'комплектующие', 'комплектующее к модели двери'], ['фрамуга', 'верхняя глухая вставка', 'алюминий', 'у ALU-005 входит в базу']],
  Задача_Клауду: [['Это вкладка с заданием — агент её не импортирует']],
